import { SpacedText } from '@zooniverse/react-components'
import { Button } from 'grommet'
import { func, node, string } from 'prop-types'
import styled, { css } from 'styled-components'

const StyledButton = styled(Button)`
  ${props => css`
    color: ${props.theme.global.colors.white};
    background: ${props.theme.global.colors['neutral-1']};`
  }
  border: none;
  border-radius: 24px;
  box-shadow: none;

  &:hover {
    ${props => css`
      color: ${props.theme.global.colors.brand};
      background: ${props.theme.global.colors['accent-1']};

      svg {
        fill: ${props.theme.global.colors.brand};
        stroke: ${props.theme.global.colors.brand};
      }
    `}
    border: none;
    box-shadow: none;
  }
`

function OptionButton({ icon, label, onClick }) {
  return (
    <StyledButton
      a11yTitle={label}
      gap='xsmall'
      icon={icon}
      label={
        <SpacedText
          size='0.78rem'
          uppercase
          weight='bold'
        >
          {label}
        </SpacedText>
      }
      onClick={onClick}
    />
  )
}

OptionButton.propTypes = {
  icon: node,
  label: string.isRequired,
  onClick: func
}

export default OptionButton
